#include <stdint.h>
#include <string.h>
#include <gpiodriver.h>
#include <stm32f407xx.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif
/* ************************************************
 * MACROS
 * *********************************************** */


/* ************************************************
 * Global Structures
 * *********************************************** */

GPIO_Handler_t externalLED, externalButton;

int main(void)
{
	memset(&externalLED, 0, sizeof(GPIO_Handler_t));
	memset(&externalButton, 0, sizeof(GPIO_Handler_t));

	// Enable Clock for Port D
	GPIO_CLKControl(GPIOD, ENABLE);

	externalLED.pGPIOBaseAddr = GPIOD;
	externalButton.pGPIOBaseAddr = GPIOD;

	externalLED.GPIOPinConfig.pinNumber = GPIO_PIN_13;
	externalLED.GPIOPinConfig.pinMode = GPIO_MODE_OUT;
	externalLED.GPIOPinConfig.pinOutputType = GPIO_OUTPUT_TYPE_PUSHPULL;
	externalLED.GPIOPinConfig.pinSpeed = GPIO_OUTPUT_SPEED_MEDIUM;
	externalLED.GPIOPinConfig.pinPullUpPullDown = GPIO_NO_PULL_UP_DOWN;

	externalButton.GPIOPinConfig.pinNumber = GPIO_PIN_14;
	externalButton.GPIOPinConfig.pinMode = GPIO_MODE_IN;
	externalButton.GPIOPinConfig.pinSpeed = GPIO_OUTPUT_SPEED_HIGH;
	externalButton.GPIOPinConfig.pinPullUpPullDown = GPIO_NO_PULL_UP_DOWN;

	GPIO_Init(&externalLED);
	GPIO_Init(&externalButton);
    /* Loop forever */

	volatile uint32_t i;
	uint8_t readValue;
	for(;;)
	{
		readValue = GPIO_ReadPortPin(GPIOD, GPIO_PIN_14);
		for(i=0;i<80000;i++); // Added a delay for reducing switch debouncing
		if(readValue != GPIO_SET_PIN)
		{
			GPIO_WritePortPin(GPIOD, externalLED.GPIOPinConfig.pinNumber, GPIO_SET_PIN);
		}
		else
		{
			GPIO_WritePortPin(GPIOD, externalLED.GPIOPinConfig.pinNumber, GPIO_CLEAR_PIN);
		}
	}
}
